import {oakComparators} from './oak-comparators.js?v=20261029-language-complete';
import {completionData} from './completion-data.js?v=20261029-language-complete';
import {sourceBank} from './source-bank.js?v=20261029-language-complete';
const official='https://www.aqa.org.uk/subjects/english/gcse/english-8700/specification';
const names={'fiction-language':'Fiction language','fiction-structure':'Fiction structure',evaluation:'Critical evaluation','creative-writing':'Descriptive and narrative writing','nonfiction-reading':'Non-fiction reading and comparison','viewpoint-writing':'Writing a viewpoint',accuracy:'Accuracy and editing',spoken:'Spoken Language'};
const oakUnits={'fiction-language':'fiction-read-around-the-world','fiction-structure':'fiction-read-around-the-world',evaluation:'fiction-books-that-changed-my-world','creative-writing':'fiction-science-fiction-writing','nonfiction-reading':'non-fiction-crime-and-punishment','viewpoint-writing':'non-fiction-letter-writing-v3731',accuracy:'writing-masters',spoken:'spoken-language-the-language-of-change'};
const freshPrompts={
 'creative-writing':['Describe a station waiting room after the last departure. Make a small change in the setting significant.','Write the opening of a story in which an ordinary parcel changes a character’s immediate plan. Do not resolve the whole plot.','Write a complete short narrative about a decision to return something. Control the time span and make the ending grow from an earlier detail.'],
 'viewpoint-writing':['Write an article for a local readership arguing a considered view about keeping a community space open later. Distinguish fact, example and opinion; do not invent verified statistics.','Write a formal letter to a headteacher arguing a considered position about a weekly independent-study session. Address a reasonable objection and make a specific request.','Write a speech for a community audience about making public information easier to access. Establish the issue, develop reasons and answer an objection.'],
 accuracy:['Edit this original passage and explain five choices: "the visitors was waiting by the gate, nobody had a key. when the caretaker arrived she checked there tickets and said its open now". Consider boundaries, agreement, homophones, possession or contraction and speech punctuation; more than one defensible version is possible.'],
 spoken:['Prepare and deliver a formal presentation on a focused topic agreed with your teacher. Rehearse audibly to a real listener, respond to their questions and record actual feedback plus a revision goal. This app cannot award the endorsement.']};
function sourceView(s,label){return{kind:'language',label,title:`${s.title} · ${s.author} · ${s.year}`,content:s.text,readingRegion:true,words:[],sourceURL:s.url};}
function question(id,stage,good,bad,why,focus,refs){return{id:`${id}.${stage}.1`,prompt:stage==='practice'?`Which worked choice best demonstrates ${focus.toLowerCase()}?`:`Which choice best applies ${focus.toLowerCase()} in this new example?`,options:[good,bad],answer:0,why,concept:`${id}.application`,conceptLabel:focus,refs};}
export const completionTopics=Object.entries(names).map(([key,title])=>({id:`english-language.${key}`,title,unit:key==='spoken'?'8700-spoken':key==='accuracy'?'8700-skills':key==='nonfiction-reading'||key==='viewpoint-writing'?'8700-paper2':'8700-paper1'}));
export const completionUnits=[{id:'8700-skills',title:'AQA GCSE English Language',paper:'Accuracy and editing · both papers'},{id:'8700-paper1',title:'AQA GCSE English Language',paper:'Paper 1 · reading and creative writing'},{id:'8700-paper2',title:'AQA GCSE English Language',paper:'Paper 2 · viewpoints and perspectives'},{id:'8700-spoken',title:'AQA GCSE English Language',paper:'Spoken Language · preparation and rehearsal'}];
const latestAssessment={};
export const completionLessons=completionData.map((r,index)=>{
 const key=r.topicId.split('.').pop(),n=Number(r.id.slice(-2));
 const [rule,a,b,why,c,d,transferWhy,output]=r.profile;
 const requested = [];
 if (/Mansfield|Laura/.test(output)) requested.push(sourceBank[0]);
 if (/Henry|Della/.test(output)) requested.push(sourceBank[1]);
 if (/Gilman/.test(output)) requested.push(sourceBank[4]);
 if(key==='fiction-language' && [2,7].includes(n)) requested.push(sourceBank[0]);
 const fictionDefault=key==='fiction-language'&&n===4?sourceBank[4]:sourceBank[(n-1)%2];
 const sources=key==='nonfiction-reading'?[sourceBank[2],sourceBank[3]]:key.startsWith('fiction')||key==='evaluation'?(requested.length?[...new Set(requested)]:[fictionDefault]):[];
 const independent=/independent|delayed|transfer|presentation rehearsal|complete short narrative/i.test(r.title);
 const revise=/feedback|redraft|revision|conference/i.test(r.title),prior=latestAssessment[key];
 const field=key==='spoken'?'Your rehearsal plan and actual feedback':key==='accuracy'?'Your edited passage and explanations':key==='creative-writing'?'Your description or narrative':key==='viewpoint-writing'?'Your argument':'Your source-based analysis';
 let independentPrompt=freshPrompts[key]?.[0]||`Using the supplied source${sources.length>1?'s':''}, ${output} Explain a supported interpretation with precise evidence.`;
 if(key==='creative-writing') independentPrompt=/descriptive response/.test(r.title)?freshPrompts[key][0]:/description transfer/.test(r.title)?'Describe a harbour just before the boats leave. Develop a meaningful change in focus or atmosphere.':/story opening/.test(r.title)?freshPrompts[key][1]:/complete short narrative/.test(r.title)?freshPrompts[key][2]:/narrative choice/.test(r.title)?'Choose ONE: write a story opening in which a familiar signal is missing; OR write a complete short narrative about deciding whether to return a key. Plan a manageable moment and make a deliberate ending.':'Choose ONE: describe a rooftop garden as the weather changes; OR write the opening of a story in which somebody changes their mind. Shape the response for the chosen task.';
 if(key==='viewpoint-writing') independentPrompt=/article/.test(r.title)?freshPrompts[key][0]:/letter or speech/.test(r.title)?'Choose ONE: '+freshPrompts[key][1]+' OR '+freshPrompts[key][2]:'Write an article for a community readership arguing a considered view about fair access to digital information. Establish the issue, use honest evidence or labelled examples, address an objection and reach a proportionate conclusion.';
 if(key==='fiction-language')independentPrompt='How does the writer present a character’s response to their surroundings in the supplied extract? Analyse a pattern of language choices, use precise references and test an alternative interpretation.';
 if(key==='fiction-structure')independentPrompt='How does the writer develop the reader’s understanding across the supplied extract? Trace the opening, a significant shift and the ending; explain the effect of their order with evidence.';
 if(key==='evaluation')independentPrompt='Evaluate the view that the supplied extract presents a completely secure situation. Weigh supporting details against counter-evidence, explain the writer’s choices and reach a qualified judgment.';
 if(key==='nonfiction-reading')independentPrompt='Task1: synthesise one similarity and one difference in how Sources A and B present developing an interest into practical activity. Task2: compare how the writers convey their attitudes towards learning or work, explaining significant methods and precise evidence from both sources. Keep synthesis distinct from methods comparison.';
 const writing=output+(key==='spoken'?' Agree the arrangements with your teacher. AQA guidance suggests a prepared presentation of no more than about ten minutes, with questions and feedback.':'')+(sources.length?' Use precise evidence from the attributed source'+(sources.length>1?'s A and B':'')+' below; keep the original worked examples separate from the author’s words.':'');
 const l={id:r.id,topicId:r.topicId,title:r.title,scope:`Workshop ${n}`,minutes:30,refs:r.refs,author:'Crash Course',rights:'original_teaching_with_attributed_public_domain_sources',checked:'29 October 2026',textType:'prose',textTitle:sources[0]?.title||'Original workshop examples',sources:[official+'/subject-content/scope-of-study',official+'/scheme-of-assessment',...sources.map(s=>s.url)],contextReading:[{label:'Official AQA scope',url:official+'/subject-content/scope-of-study'},{label:'Open Government Licence',url:'https://www.nationalarchives.gov.uk/doc/open-government-licence/version/3/'},{label:'Oak unit comparator',url:oakComparators[oakUnits[key]] || 'https://open-api.thenational.academy/docs'},...sources.map(s=>({label:`Read ${s.title}`,url:s.url}))],
 sourceNote:`All instructions, contrasted examples and questions are original Crash Course work. Attributed extracts retain the public-domain authors’ wording with whitespace normalised. ${sources.map(s=>`${s.author}, ${s.title} (${s.year}): ${s.note}`).join(' ')} Repeated sources are study/revision material, not automatically unseen. Source dates and experiences must be distinguished. No official paper, marked writing or Spoken Language award is supplied. Curriculum comparisons draw on Oak National Academy English lesson metadata licensed under Open Government Licence (OGL); no Oak transcript or protected passage is reproduced. ${sources.some(x=>x.year<1900)&&key!=='nonfiction-reading'?'Nineteenth-century fiction here is comparative study; Paper 1 reading sources are twentieth- or twenty-first-century prose fiction.':''} Specialist review remains pending.`,
 explorerNote:'Original worked examples are labelled separately from authentic source extracts. Knowledge choices do not mark writing or spoken performance.',
 writing,writingSources:sources,writingLabel:key==='spoken'?'Prepare, rehearse & reflect':key==='accuracy'?'Edit & explain':'Write, review & revise',outputLabel:field,outputHelp:writing,reviewHeading:key==='spoken'?'Rehearsal review':'Review your response',requireDraft:!independent,hideSupportDuringCheck:true,
 cards:[['Understand the distinction',`${rule} Compare these original worked versions: A — ${a} B — ${b} ${why} Explain the meaningful difference before naming a device or applying a rule. The relevant decision is tied to this task, not a universal claim that one feature always produces the same response.`],['Work through the decision',`${why} The weaker version is: ${b} Identify exactly where it loses precision, control or support. A label alone does not repair it. ${sources.length?'Read the attributed longer extract and test how the same distinction applies there; do not quote our original example as the author’s wording.':'Try the distinction in a complete paragraph, checking how it serves the stated audience and purpose.'}`],['Apply, review and transfer',`${output} Keep your first version so that later revision is visible. ${key==='spoken'?'Rehearse aloud and ask a real listener for questions and feedback; writing a plan is not a delivered presentation.':'Reread for meaning before checking spelling, boundaries and punctuation.'} A saved draft records work, not a teacher’s judgment of its quality. Then attempt the different example in Check without the worked reasoning.`]],
 views:[{kind:'language',label:'Compare worked examples',title:'Original worked examples · not a quotation',content:`A: ${a}\n\nB: ${b}`,readingRegion:true,words:[['The distinction',rule],['Why A works here',why],['What to try',output]]},...sources.map((s,i)=>sourceView(s,`Source ${i===0?'A':'B'} · ${s.author}`)),{kind:'people',label:'Plan and test',title:'From choice to response',rows:[['Purpose',rule],['Task',writing],['Review','Check the actual effect and support; explain a specific revision rather than counting devices.']]}],
 tasks:[[`Which original worked version best demonstrates ${r.title.toLowerCase()}?`,[a,b],0,why,`Test the distinction: ${rule} ${why}`]],
 practice:[question(r.id,'practice',a,b,why,r.title,r.refs)],check:[question(r.id,'check',c,d,transferWhy,r.title,r.refs)],
 rubric:[`Meet the specific task: ${output}`,`${key==='spoken'?'Record actual delivery and listener responses; do not invent feedback.':sources.length?'Use precise accurate source evidence and explain rather than simply label choices.':'Control language, organisation and accuracy for your chosen purpose and audience.'}`,`Explain one deliberate choice or revision: ${rule}`],
 ...(revise&&prior?{revisionFrom:prior}:{}),
 ...(independent?{independentWriting:true,...(key==='spoken'?{independentHeading:'Presentation rehearsal',independentStartLabel:'Start rehearsal log →'}:{}),independentTaskType:key==='spoken'?'presentation-rehearsal':key.includes('writing')?'composition':key==='accuracy'?'editing':'reading-response',independentTaskLabel:key==='spoken'?'Preparation and live rehearsal log · actual teacher assessment remains required.':'Original independent response task · saved first response and later revision kept separately.',independentIntro:`${key==='spoken'?'Rehearse aloud and record actual listener questions and feedback.':'Plan, respond and check your work.'} About 30 minutes is an advisory workshop estimate, not an enforced limit. ${sources.length?'Previously studied extracts make this revision rather than genuinely unseen reading. ':''}Writing and performance require human review; no automatic grade is assigned.`,independentPrompt,independentExtract:sources.map((s,i)=>`SOURCE ${i===0?'A':'B'} · ${s.author}, ${s.title} (${s.year})\n\n${s.text}`).join('\n\n────────\n\n'),independentExtractLabel:sources.length?'Attributed studied source(s) · familiarity must be acknowledged':'A new original task; no model response supplied during your attempt.',feedbackConference:['Which exact passage or decision in your response needs improvement?','What did an actual reader or listener say, if you have feedback? Keep self-review distinct.','What will you change, why, and how will you test the revision?']}:{}),
 };
 if(independent)latestAssessment[key]=l.id;
 return l;
});
